import unittest
from text_utils import word_frequencies

class FrequencyTests(unittest.TestCase):
    def test_order_and_case(self):
        self.assertEqual(word_frequencies('Blue red BLUE green red blue'), [('blue', 3), ('red', 2), ('green', 1)])
    def test_separators(self):
        self.assertEqual(word_frequencies('A1a...B-b'), [('a', 2), ('b', 2)])
    def test_empty(self):
        self.assertEqual(word_frequencies('123 !!!'), [])

if __name__ == '__main__':
    unittest.main()

